function escapeHtml(value: unknown): string {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function parseCommandCenterAddress(input: string): { address: string; city: string; state: string; zip?: string } | null {
  const cleaned = input.trim().replace(/\s+/g, ' ');
  const match = cleaned.match(/^(.+?),\s*([^,]+),\s*([A-Za-z]{2})(?:\s+(\d{5})(?:-\d{4})?)?$/);
  if (!match) return null;
  return {
    address: match[1].trim(),
    city: match[2].trim(),
    state: match[3].toUpperCase(),
    ...(match[4] ? { zip: match[4] } : {}),
  };
}

function renderCommandCenterHtml(): string {
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>MXRE Command Center</title>
  <style>
    :root{color-scheme:dark;--bg:#0b1115;--panel:#121a20;--panel2:#17222a;--line:#2b3a43;--text:#edf6fb;--muted:#9eb0ba;--green:#49dc8b;--blue:#63b3ff;--amber:#f7c65f;--red:#ff8171}
    *{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
    main{width:min(1240px,calc(100% - 28px));margin:0 auto;padding:24px 0 36px}
    header{display:flex;justify-content:space-between;gap:20px;align-items:flex-end;padding:28px 0 22px;border-bottom:1px solid var(--line)}
    h1{font-size:clamp(2.8rem,8vw,6.8rem);line-height:.9;margin:0;letter-spacing:0}.eyebrow{color:var(--green);font-weight:900;text-transform:uppercase;margin:0 0 8px}.muted{color:var(--muted)}.source{color:var(--blue);font-size:.9rem}
    form{display:grid;grid-template-columns:minmax(260px,1fr) 190px 92px;gap:10px;align-items:end;margin:22px 0}
    label{display:block;color:var(--muted);font-size:.82rem;font-weight:800;margin:0 0 8px}input,select,button{width:100%;min-height:48px;border-radius:8px;border:1px solid var(--line);font:inherit}
    input,select{background:#0f1519;color:var(--text);padding:0 12px}button{background:var(--green);color:#06120a;font-weight:900;cursor:pointer}button:disabled{opacity:.65;cursor:wait}
    .tabs{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0}.tab{width:auto;min-height:40px;background:#101820;color:var(--muted);border-color:var(--line);padding:0 14px}.tab.active{background:#183323;color:#e8fff0;border-color:#2c8052}
    .status{min-height:24px;color:var(--muted);margin:0 0 18px}.status.error{color:var(--red)}
    .grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:8px;padding:16px;min-height:150px}.wide{grid-column:span 2}.full{grid-column:1/-1}
    .head{display:flex;justify-content:space-between;gap:12px;margin-bottom:12px}.head strong{color:var(--green);text-transform:uppercase;font-size:.78rem}.pill{color:var(--amber);font-size:.78rem;font-weight:900}
    .metric{font-size:2rem;font-weight:950}.small{font-size:.86rem;color:var(--muted);line-height:1.45}dl{display:grid;gap:8px;margin:0}div.row{display:grid;grid-template-columns:130px 1fr;gap:10px;padding:8px 0;border-top:1px solid rgba(255,255,255,.07)}dt{color:var(--muted)}dd{margin:0;font-weight:800;overflow-wrap:anywhere}
    pre{height:430px;overflow:auto;background:#080d10;border:1px solid var(--line);border-radius:8px;padding:14px;font-size:.82rem;line-height:1.5;white-space:pre-wrap}
    table{width:100%;border-collapse:collapse;font-size:.86rem}th,td{text-align:left;padding:10px;border-top:1px solid rgba(255,255,255,.08);vertical-align:top}th{color:var(--muted);font-size:.78rem;text-transform:uppercase}
    tr.clickable{cursor:pointer}tr.clickable:hover{background:rgba(255,255,255,.04)}.nowrap{white-space:nowrap}.detail-scroll{max-height:720px;overflow:auto;border:1px solid rgba(255,255,255,.08);border-radius:8px}
    @media(max-width:900px){header,form,.grid{grid-template-columns:1fr}.wide{grid-column:auto}}
  </style>
</head>
<body>
<main>
  <header>
    <div><p class="eyebrow">MXRE</p><h1>Command Center</h1><p class="muted">Exact address lookup and market panels backed by the existing MXRE API contracts.</p></div>
    <div class="source">Local preview: /preview/command-center</div>
  </header>
  <nav class="tabs">
    <button class="tab active" type="button" data-tab="lookup">Address Lookup</button>
    <button class="tab" type="button" data-tab="selfStorage">Self-storage Report</button>
  </nav>
  <section id="lookupTab">
  <form id="form">
    <div><label for="q">Address</label><input id="q" value="8203 W 88th St, Indianapolis, IN 46278" autocomplete="street-address"></div>
    <div><label for="asset">Market asset panel</label><select id="asset"><option value="single_family">Single-family</option><option value="self_storage">Self-storage</option><option value="multifamily">Multifamily</option></select></div>
    <button id="run" type="submit">Run</button>
  </form>
  <p id="status" class="status">Ready.</p>
  <section class="grid">
    <article class="panel wide"><div class="head"><strong>Matched Property</strong><span id="confidence" class="pill">Idle</span></div><h2 id="addr">No lookup yet</h2><dl id="facts"></dl></article>
    <article class="panel"><div class="head"><strong>Valuation</strong></div><div id="value" class="metric">--</div><p id="valueNote" class="small"></p></article>
    <article class="panel"><div class="head"><strong>Debt / Equity</strong></div><div id="equity" class="metric">--</div><p id="debtNote" class="small"></p></article>
    <article class="panel"><div class="head"><strong>Selected Market Panel</strong><span id="panelAsset" class="pill"></span></div><div id="panelCount" class="metric">--</div><p id="panelNote" class="small"></p></article>
    <article class="panel"><div class="head"><strong>External Evidence</strong></div><div id="externalCount" class="metric">--</div><p id="externalNote" class="small"></p></article>
    <article class="panel full"><div class="head"><strong>External Top Listings</strong><span class="pill">Verified rows only</span></div><div id="externalTable"></div></article>
    <article class="panel full"><div class="head"><strong>Raw MXRE Return Data</strong><span id="schema" class="pill"></span></div><pre id="json">{}</pre></article>
  </section>
  </section>
  <section id="selfStorageTab" style="display:none">
    <section class="grid">
      <article class="panel"><div class="head"><strong>Parcel-backed</strong></div><div id="ssParcel" class="metric">--</div><p class="small">County assessor parcel rows classified as self-storage.</p></article>
      <article class="panel"><div class="head"><strong>Facility evidence</strong></div><div id="ssFacility" class="metric">--</div><p class="small">Operating facility rows from public OpenStreetMap tags.</p></article>
      <article class="panel"><div class="head"><strong>Verified listings</strong></div><div id="ssListings" class="metric">--</div><p class="small">Accepted public listing/detail evidence, active and historical.</p></article>
      <article class="panel"><div class="head"><strong>Active listing evidence</strong></div><div id="ssActive" class="metric">--</div><p class="small">Verified public rows currently marked active.</p></article>
      <article class="panel full"><div class="head"><strong>All-Market Self-storage Summary</strong><span id="ssGenerated" class="pill"></span></div><p class="small">Click a market row to drill into every parcel-backed self-storage record and every external evidence row.</p><div id="ssTable"><p class="small">Loading self-storage report...</p></div></article>
      <article class="panel full" id="ssDetailPanel" style="display:none"><div class="head"><strong id="ssDetailTitle">Market Detail</strong><span id="ssDetailCount" class="pill"></span></div><div class="status" id="ssDetailStatus"></div><div id="ssDetailTable"></div></article>
      <article class="panel full"><div class="head"><strong>Source Definitions</strong><span class="pill">Important</span></div><div id="ssDefinitions" class="small"></div></article>
    </section>
  </section>
</main>
<script>
const apiKey = ${JSON.stringify(process.env.MXRE_API_KEY ?? loadApiClients()[0]?.key ?? '')};
const $ = (id) => document.getElementById(id);
const fmt = (n) => typeof n === 'number' ? new Intl.NumberFormat().format(n) : '--';
const money = (n) => typeof n === 'number' ? new Intl.NumberFormat(undefined,{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n) : '--';
function setStatus(text, error=false){$('status').textContent=text;$('status').classList.toggle('error',error)}
function row(k,v){return '<div class="row"><dt>'+esc(k)+'</dt><dd>'+esc(v ?? '--')+'</dd></div>'}
function esc(v){return String(v ?? '').replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function setTab(tab){
  document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active', b.dataset.tab===tab));
  $('lookupTab').style.display = tab === 'lookup' ? '' : 'none';
  $('selfStorageTab').style.display = tab === 'selfStorage' ? '' : 'none';
  if(tab === 'selfStorage') loadSelfStorage();
}
document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>setTab(b.dataset.tab)));
function render(data){
  $('json').textContent = JSON.stringify(data, null, 2);
  $('schema').textContent = data.schemaVersion || '';
  const propWrap = data.endpoints?.property;
  const prop = propWrap?.body;
  if(propWrap && propWrap.ok){
    const p = prop.property || {}, o = prop.ownership || {}, v = prop.valuation || {}, d = prop.debtAndLiens || {};
    $('confidence').textContent = prop.request?.confidence || 'Matched';
    $('addr').textContent = [p.address,p.city,p.state,p.zip].filter(Boolean).join(', ');
    $('facts').innerHTML = row('MXRE ID', prop.mxreId) + row('Parcel / APN', p.parcelId || p.apn) + row('Asset', [p.assetType,p.assetSubtype].filter(Boolean).join(' / ')) + row('Units', p.unitCount) + row('Owner', o.ownerName) + row('Year built', p.yearBuilt);
    $('value').textContent = money(v.marketValue || v.estimatedValue || v.assessedValue);
    $('valueNote').textContent = 'Assessed: '+money(v.assessedValue)+' | Tax year: '+(v.taxYear || '--');
    $('equity').textContent = money(d.estimatedEquity || d.equityValue);
    $('debtNote').textContent = 'Open balance: '+money(d.openMortgageBalance)+' | Free/clear: '+(d.freeClear ?? '--');
  } else {
    $('confidence').textContent = propWrap ? 'No MXRE match' : 'Address not parsed';
    $('addr').textContent = propWrap?.body?.error || 'Use: street, city, ST zip';
    $('facts').innerHTML = '';
    $('value').textContent = '--'; $('valueNote').textContent = ''; $('equity').textContent = '--'; $('debtNote').textContent = '';
  }
  const panel = data.endpoints?.assetDashboard?.body || {};
  const inv = panel.inventory || {}, om = panel.on_market || {};
  $('panelAsset').textContent = data.request?.selectedMarketPanel?.assetClass || '';
  $('panelCount').textContent = fmt(inv.total_properties);
  $('panelNote').textContent = 'Selected Indianapolis market panel only. The exact property asset is shown above from /v1/bbc/property. Active internal listing rows: '+fmt(om.active_listing_rows)+'.';
  $('externalCount').textContent = fmt(om.external_listing_rows);
  $('externalNote').textContent = 'Rows from external_market_listings for the selected market panel and status=active.';
  const external = om.external_top_listings || [];
  $('externalTable').innerHTML = external.length ? '<table><thead><tr><th>Title</th><th>Address</th><th>Units</th><th>Source</th><th>Broker</th></tr></thead><tbody>'+external.map(r => '<tr><td>'+esc(r.title)+'</td><td>'+esc([r.address,r.city,r.state,r.zip].filter(Boolean).join(', '))+'</td><td>'+esc(r.units || r.portfolioUnits || '')+'</td><td>'+esc(r.source)+'</td><td>'+esc(r.broker)+'</td></tr>').join('')+'</tbody></table>' : '<p class="small">No active external evidence rows returned.</p>';
}
let selfStorageLoaded=false;
let selfStorageDetailMarket='';
async function loadSelfStorage(){
  if(selfStorageLoaded) return;
  const res = await fetch('/preview/command-center/self-storage', { headers: apiKey ? { 'x-api-key': apiKey } : {} });
  const data = await res.json();
  if(!res.ok){
    $('ssTable').innerHTML = '<p class="small" style="color:var(--red)">'+esc(data.error || 'Self-storage report failed')+'</p>';
    return;
  }
  selfStorageLoaded = true;
  const t = data.totals || {};
  $('ssParcel').textContent = fmt(t.parcelBackedCount);
  $('ssFacility').textContent = fmt(t.operatingFacilityEvidence);
  $('ssListings').textContent = fmt(t.verifiedListingEvidence);
  $('ssActive').textContent = fmt(t.activeListingEvidence);
  $('ssGenerated').textContent = data.generated_at ? new Date(data.generated_at).toLocaleString() : '';
  $('ssDefinitions').innerHTML = Object.entries(data.definitions || {}).map(([k,v]) => '<div class="row"><dt>'+esc(k)+'</dt><dd>'+esc(v)+'</dd></div>').join('');
  const rows = data.markets || [];
  $('ssTable').innerHTML = '<table><thead><tr><th>Market</th><th>Parcel-backed</th><th>Facility evidence</th><th>Verified listings</th><th>Active listings</th><th>Total evidence</th><th>Examples</th></tr></thead><tbody>'
    + rows.map(r => {
      const examples = (r.examples || []).slice(0,3).map(x => '<div><a href="'+esc(x.sourceUrl||'#')+'" target="_blank" rel="noopener noreferrer">'+esc(x.title || x.address || 'Evidence')+'</a><div class="small">'+esc([x.address,x.city,x.state,x.zip].filter(Boolean).join(', '))+' · '+esc(x.source)+' · '+esc(x.status)+'</div></div>').join('');
      return '<tr class="clickable" data-ss-market="'+esc(r.market || '')+'" data-ss-label="'+esc(r.label || r.market || '')+'"><td><strong>'+esc(r.label || r.market)+'</strong><div class="small">'+esc(r.market)+'</div></td><td>'+fmt(r.parcelBackedCount)+'</td><td>'+fmt(r.operatingFacilityEvidence)+'</td><td>'+fmt(r.verifiedListingEvidence)+'</td><td>'+fmt(r.activeListingEvidence)+'</td><td>'+fmt(r.externalEvidenceCount)+'</td><td>'+examples+'</td></tr>';
    }).join('') + '</tbody></table>';
  document.querySelectorAll('[data-ss-market]').forEach(row => row.addEventListener('click', event => {
    if(event.target.closest('a')) return;
    loadSelfStorageMarket(row.dataset.ssMarket, row.dataset.ssLabel);
  }));
}
function renderSelfStorageValue(row){
  if(typeof row.listPrice === 'number') return money(row.listPrice);
  if(typeof row.marketValue === 'number') return money(row.marketValue);
  if(typeof row.assessedValue === 'number') return money(row.assessedValue);
  return '--';
}
function renderSelfStorageSource(row){
  if(row.recordType === 'parcel_backed') return 'MXRE parcel';
  return [row.source, row.evidenceType].filter(Boolean).join(' / ') || 'External evidence';
}
async function loadSelfStorageMarket(market,label){
  if(!market) return;
  selfStorageDetailMarket = market;
  $('ssDetailPanel').style.display = '';
  $('ssDetailTitle').textContent = (label || market) + ' Self-storage Detail';
  $('ssDetailCount').textContent = 'Loading...';
  $('ssDetailStatus').textContent = 'Loading every row for '+(label || market)+'...';
  $('ssDetailTable').innerHTML = '';
  const res = await fetch('/preview/command-center/self-storage/' + encodeURIComponent(market), { headers: apiKey ? { 'x-api-key': apiKey } : {} });
  const data = await res.json();
  if(selfStorageDetailMarket !== market) return;
  if(!res.ok){
    $('ssDetailCount').textContent = 'Error';
    $('ssDetailStatus').textContent = data.error || 'Market detail failed';
    $('ssDetailStatus').classList.add('error');
    return;
  }
  $('ssDetailStatus').classList.remove('error');
  const totals = data.totals || {};
  const rows = data.rows || [];
  $('ssDetailCount').textContent = fmt(totals.parcelBacked) + ' parcel-backed / ' + fmt(totals.combinedRows) + ' total rows';
  $('ssDetailStatus').textContent = 'Parcel-backed: '+fmt(totals.parcelBacked)+' | External evidence: '+fmt(totals.externalEvidence)+' | Active listing evidence: '+fmt(totals.activeListingEvidence)+' | Facility evidence: '+fmt(totals.facilityEvidence);
  $('ssDetailTable').innerHTML = rows.length ? '<div class="detail-scroll"><table><thead><tr><th>Type</th><th>Status</th><th>Address</th><th>Owner / Title</th><th>MXRE / Parcel ID</th><th>Source / Confidence</th><th>Value / Price</th><th>Link</th></tr></thead><tbody>'
    + rows.map(row => {
      const address = [row.address,row.city,row.state,row.zip].filter(Boolean).join(', ');
      const ownerOrTitle = row.ownerName || row.title || '--';
      const ids = row.recordType === 'parcel_backed'
        ? 'MXRE '+esc(row.mxreId)+'<div class="small">'+esc(row.parcelId || '')+'</div>'
        : esc(row.externalListingId || row.mxreId || '');
      const confidence = [renderSelfStorageSource(row), row.assetConfidence || row.confidence].filter(Boolean).join(' | ');
      const url = row.listingUrl || row.sourceUrl;
      const link = url ? '<a href="'+esc(url)+'" target="_blank" rel="noopener noreferrer">Open</a>' : '--';
      return '<tr><td class="nowrap">'+esc(row.recordType)+'</td><td class="nowrap">'+esc(row.status || '--')+'</td><td>'+esc(address || '--')+'</td><td>'+esc(ownerOrTitle)+'</td><td>'+ids+'</td><td>'+esc(confidence || '--')+'</td><td class="nowrap">'+esc(renderSelfStorageValue(row))+'</td><td>'+link+'</td></tr>';
    }).join('') + '</tbody></table></div>' : '<p class="small">No rows returned for this market.</p>';
}
$('form').addEventListener('submit', async (event) => {
  event.preventDefault();
  $('run').disabled = true;
  setStatus('Loading MXRE data...');
  try {
    const params = new URLSearchParams({ q: $('q').value.trim(), asset_class: $('asset').value });
    const res = await fetch('/preview/command-center/data?' + params.toString());
    const data = await res.json();
    render(data);
    setStatus(res.ok ? 'Loaded from MXRE API endpoints.' : (data.error || 'Lookup failed'), !res.ok);
  } catch (error) {
    setStatus(error.message || 'Lookup failed', true);
  } finally {
    $('run').disabled = false;
  }
});
$('form').dispatchEvent(new Event('submit'));
</script>
</body>
</html>`;
}

async function fetchAndRespond(
  c: Context,
  id: number,
  responseMapper: (response: ReturnType<typeof buildPropertyResponse>) => unknown = (response) => response,
) {
  let props: Record<string, unknown>[];
  try {
    props = await queryPg<Record<string, unknown>>(`
      select
        p.*,
        row_to_json(c)::jsonb as counties
      from properties p
      left join counties c on c.id = p.county_id
      where p.id = ${id}
      limit 1;
    `);
  } catch (error) {
    return c.json({ error: 'Database error', detail: error instanceof Error ? error.message : String(error) }, 500);
  }
  if (!props || props.length === 0) {
    return c.json({ error: 'Property not found' }, 404);
  }

  try {
    return await assembleResponse(c, props[0], responseMapper);
  } catch (error) {
    console.error('BBC property response assembly failed', {
      propertyId: id,
      message: error instanceof Error ? error.message : String(error),
    });
    return c.json({ error: 'Database error' }, 500);
  }
}

async function assembleResponse(
  c: Context,
  property: Record<string, unknown>,
  responseMapper: (response: ReturnType<typeof buildPropertyResponse>) => unknown = (response) => response,
) {
  const id = property.id as number;
  // counties may be an array (when joined without !inner) or a single object
  const rawCounty = property.counties;
  const countyData: Record<string, unknown> = (Array.isArray(rawCounty) ? rawCounty[0] : rawCounty) ?? {
    county_name: '',
    state_code: property.state_code ?? '',
    county_fips: null,
    state_fips: null,
  };

  const [mortgages, rents, listingsById, saleHistory, mlsHistory, foreclosureData, publicSignals, demo] = await Promise.all([
    queryPg<Record<string, unknown>>(`
      select id,property_id,document_type,loan_amount,original_amount,estimated_current_balance,estimated_monthly_payment,interest_rate,interest_rate_type,rate_source,rate_match_confidence,term_months,maturity_date,recording_date,document_number,book_page,lender_name,lender_type,borrower_name,loan_type,source_url,grantee_name,open,position
      from mortgage_records
      where property_id = ${id}
      order by recording_date desc nulls last
      limit 50;
    `),
    queryPg<Record<string, unknown>>(`
      select *
      from rent_snapshots
      where property_id = ${id}
      order by observed_at desc nulls last
      limit 24;
    `),
    queryPg<Record<string, unknown>>(`
      select *
      from listing_signals
      where property_id = ${id}
      order by is_on_market desc, last_seen_at desc nulls last, first_seen_at desc nulls last
      limit 20;
    `),
    queryPg<Record<string, unknown>>(`
      select *
      from sale_history
      where property_id = ${id}
      order by recording_date desc nulls last
      limit 20;
    `),
    queryPg<Record<string, unknown>>(`
      select *
      from mls_history
      where property_id = ${id}
      order by status_date desc nulls last
      limit 20;
    `),
    queryPg<Record<string, unknown>>(`
      select *
      from foreclosures
      where property_id = ${id}
      limit 10;
    `),
    queryPg<Record<string, unknown>>(`
      select *
      from property_public_signals
      where property_id = ${id}
      order by observed_date desc nulls last
      limit 50;
    `),
    fetchRentBaselineDemographics(property, countyData),
  ]);

  // Listing signals: fall back to address+state match if property_id lookup is empty
  let listings = listingsById;
  if (listingsById.length === 0 && property.address) {
    const addrClean = (property.address as string).replace(/[,()]/g, ' ').trim();
    const stateCode = (countyData.state_code as string ?? '').toUpperCase();
    const byAddr = await queryPg<Record<string, unknown>>(`
      select *
      from listing_signals
      where address ilike '${sqlString(addrClean)}'
        and state_code = '${sqlString(stateCode)}'
      order by is_on_market desc, last_seen_at desc nulls last, first_seen_at desc nulls last
      limit 10;
    `);
    if (byAddr.length > 0) listings = byAddr;
  }

  const response = buildPropertyResponse(
    property,
    countyData,
    mortgages,
    rents,
    listings,
    saleHistory,
    mlsHistory,
    (demo.data as Record<string, unknown> | null) ?? null,
    foreclosureData,
    publicSignals,
  );

  return c.json(sanitizeJsonValue(responseMapper(response)));
}

function sanitizeJsonValue(value: unknown): unknown {
  if (typeof value === 'bigint') return value.toString();
  if (value instanceof Date) return value.toISOString();
  if (Array.isArray(value)) return value.map((item) => sanitizeJsonValue(item));
  if (value && typeof value === 'object') {
    return Object.fromEntries(
      Object.entries(value as Record<string, unknown>)
        .map(([key, item]) => [key, sanitizeJsonValue(item)]),
    );
  }
  return value;
}

async function fetchRentBaselineDemographics(
  property: Record<string, unknown>,
  countyData: Record<string, unknown>,
): Promise<{ data: Record<string, unknown> | null; error: unknown | null }> {
  const zip = String(property.zip ?? '').slice(0, 5);
  const stateFips = String(countyData.state_fips ?? '');
  const countyFips = String(countyData.county_fips ?? '');
  const fullCountyFips = countyFips.length === 5 ? countyFips : `${stateFips}${countyFips}`;

  const buildFmr = (rows: Array<Record<string, unknown>>): Record<string, unknown> | null => {
    if (rows.length === 0) return null;

    const byBedroom = new Map<number, Record<string, unknown>>();
    for (const row of rows) {
      if (typeof row.bedrooms === 'number') byBedroom.set(row.bedrooms, row);
    }
    const year = Math.max(...rows.map((row) => Number(row.vintage_year ?? 0)));

    return {
      fmr_0: byBedroom.get(0)?.median_rent ?? null,
      fmr_1: byBedroom.get(1)?.median_rent ?? null,
      fmr_2: byBedroom.get(2)?.median_rent ?? null,
      fmr_3: byBedroom.get(3)?.median_rent ?? null,
      fmr_4: byBedroom.get(4)?.median_rent ?? null,
      fmr_year: year || null,
      hud_area_name: rows[0]?.geography_type === 'zip' ? `ZIP ${rows[0].geography_id}` : `County ${rows[0]?.geography_id}`,
      median_income: null,
      source: rows[0]?.source ?? 'rent_baselines',
    };
  };

  if (zip) {
    const data = await queryPg<Record<string, unknown>>(`
      select source,geography_type,geography_id,bedrooms,median_rent,vintage_year
      from rent_baselines
      where geography_type = 'zip'
        and geography_id = '${sqlString(zip)}'
      order by vintage_year desc nulls last;
    `);
    if (data.length > 0) return { data: buildFmr(data), error: null };
  }

  if (fullCountyFips.length === 5) {
    const data = await queryPg<Record<string, unknown>>(`
      select source,geography_type,geography_id,bedrooms,median_rent,vintage_year
      from rent_baselines
      where geography_type = 'county'
        and geography_id = '${sqlString(fullCountyFips)}'
      order by vintage_year desc nulls last;
    `);
    if (data.length > 0) return { data: buildFmr(data), error: null };
  }

  return { data: null, error: null };
}

// ── Start server ─────────────────────────────────────────────
const port = parseInt(process.env.PORT ?? process.env.MXRE_API_PORT ?? '3100', 10);
const hostname = process.env.HOST ?? process.env.MXRE_API_HOST ?? '127.0.0.1';

serve({ fetch: app.fetch, port, hostname }, (info) => {
  console.log(`MXRE Property API running on http://${hostname}:${info.port}`);
});

export { app };


